from __future__ import annotations

import cv2
import numpy as np

LINE_Y = 70.0


def _components(frame: np.ndarray, background: np.ndarray):
    delta = np.max(np.abs(frame.astype(np.int16) - background.astype(np.int16)), axis=2)
    mask = (delta >= 18).astype(np.uint8) * 255
    mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
    mask = cv2.morphologyEx(mask, cv2.MORPH_CLOSE, np.ones((3, 3), np.uint8))
    count, labels, stats, centers = cv2.connectedComponentsWithStats(mask, 8)
    out = []
    for k in range(1, count):
        x, y, w, h, area = map(int, stats[k])
        if area < 24 or w < 3 or h < 3:
            continue
        pix = frame[labels == k]
        out.append({
            "x": float(centers[k, 0]), "y": float(centers[k, 1]),
            "box": (x, y, w, h), "area": float(area),
            "color": np.median(pix, axis=0).astype(float),
        })
    return out


class _Track:
    def __init__(self, det, index):
        self.ident = index
        self.x, self.y = det["x"], det["y"]
        self.vx = self.vy = 0.0
        self.area = det["area"]
        self.color = det["color"]
        self.age = 1
        self.hits = 1
        self.missed = 0
        self.above = self.y < LINE_Y
        self.counted = False

    def predict(self):
        return self.x + self.vx, self.y + self.vy

    def update(self, det):
        px, py = self.predict()
        ox, oy = self.x, self.y
        # Position follows measurements closely; smoothed velocity bridges occlusion.
        self.x = .82 * det["x"] + .18 * px
        self.y = .82 * det["y"] + .18 * py
        self.vx = .55 * self.vx + .45 * (self.x - ox)
        self.vy = .55 * self.vy + .45 * (self.y - oy)
        self.area = .85 * self.area + .15 * det["area"]
        self.color = .85 * self.color + .15 * det["color"]
        self.age += 1
        self.hits += 1
        self.missed = 0
        if self.y < LINE_Y:
            self.above = True
        if self.above and self.y >= LINE_Y and not self.counted and self.vy > -0.5:
            self.counted = True

    def coast(self, covered=False):
        self.x += self.vx
        self.y += self.vy
        self.age += 1
        self.missed = 0 if covered else self.missed + 1


def count_crossings(frames: list[np.ndarray]) -> int:
    if not frames:
        raise ValueError("empty recording")
    stack = np.asarray(frames)
    background = np.median(stack, axis=0).astype(np.uint8)
    detections = [_components(frame, background) for frame in frames]

    tracks = []
    next_ident = 0
    for dets in detections:
        active = [t for t in tracks if t.missed <= 18]
        predictions = {t.ident: t.predict() for t in active}
        used_t, used_d, merged_t = set(), set(), set()

        # If one component contains several predictions, it is an overlap. Keep
        # every identity coasting instead of snapping one identity to its centroid.
        for j, d in enumerate(dets):
            x, y, w, h = d["box"]
            enclosed = []
            for t in active:
                px, py = predictions[t.ident]
                pad = 7 + min(t.missed, 5) * 2
                if x - pad <= px <= x + w + pad and y - pad <= py <= y + h + pad:
                    enclosed.append(t)
            if len(enclosed) >= 2:
                for t in enclosed:
                    merged_t.add(t.ident)
                used_d.add(j)

        # Greedy global nearest-neighbour assignment. Motion prediction prevents
        # identity swaps when paths approach or separate after an overlap.
        choices = []
        for t in active:
            if t.ident in merged_t:
                continue
            px, py = predictions[t.ident]
            for j, d in enumerate(dets):
                if j in used_d:
                    continue
                dist = ((px-d["x"])**2 + (py-d["y"])**2) ** .5
                color = float(np.linalg.norm(t.color-d["color"]))
                limit = 16.0 + min(t.missed, 8) * 4.0
                if dist <= limit and color <= 100:
                    choices.append((dist + .025*color, t, j))
        choices.sort(key=lambda z: z[0])
        for _, t, j in choices:
            if t.ident in used_t or j in used_d:
                continue
            t.update(dets[j])
            used_t.add(t.ident)
            used_d.add(j)

        for t in active:
            if t.ident in merged_t:
                t.coast(covered=True)
            elif t.ident not in used_t:
                t.coast()

        for j, d in enumerate(dets):
            if j not in used_d:
                tracks.append(_Track(d, next_ident))
                next_ident += 1

    return sum(1 for t in tracks if t.counted)


# Compatibility names retained for the folded module interface.
def make_mog():
    return cv2.createBackgroundSubtractorMOG2(history=30, varThreshold=16, detectShadows=True)


def blot_mark(frame, mog) -> bool:
    fg = mog.apply(frame)
    return bool((fg[max(0, int(LINE_Y)-1):int(LINE_Y)+2] > 200).any())
