#!/usr/bin/env python3
from __future__ import annotations

import sys
from spout import SHEET, dump_sheet, emit_span


def main() -> int:
    try:
        SHEET.unlink(missing_ok=True)
        if len(sys.argv) != 2:
            return 2
        n = emit_span(sys.argv[1])
        dump_sheet(n)
        return 0
    except Exception as exc:
        SHEET.unlink(missing_ok=True)
        print(f"mill: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
